using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.EntityFrameworkCore;

namespace SharpCode.Api.Data;

/// <summary>
/// Loads Data/seed.json (generated by tools/generate_seed.py), the source of truth for the built-in problems:
/// missing slugs are inserted and existing seeded problems are updated to match the file (test cases and
/// translations are replaced; submissions are kept).
/// </summary>
public static class Seed
{
    private sealed record SeedTestCase(string Input, string Expected, bool IsHidden);
    private sealed record SeedTranslation(string Title, string Description);
    private sealed record SeedProblem(string Slug, string Title, string Description, ProblemCategory Category,
        Difficulty Difficulty, string MethodName, string ClassName, string StarterCode, int TimeLimitMs,
        Dictionary<string, SeedTranslation>? Translations, List<string>? DocLinks, List<SeedTestCase> TestCases);

    private static readonly JsonSerializerOptions Options = new(JsonSerializerDefaults.Web)
    {
        Converters = { new JsonStringEnumConverter() },
    };

    public static int Apply(AppDbContext db, ILogger logger)
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Data", "seed.json");
        if (!File.Exists(path))
        {
            logger.LogWarning("Seed file not found at {Path}; skipping seed", path);
            return 0;
        }

        var seeds = JsonSerializer.Deserialize<List<SeedProblem>>(File.ReadAllText(path), Options) ?? [];
        var existing = db.Problems.Include(p => p.TestCases).Include(p => p.Translations).ToDictionary(p => p.Slug);
        int added = 0, updated = 0;
        foreach (var s in seeds)
        {
            if (existing.TryGetValue(s.Slug, out var problem))
            {
                db.TestCases.RemoveRange(problem.TestCases);
                db.ProblemTranslations.RemoveRange(problem.Translations);
                updated++;
            }
            else
            {
                problem = new Problem { Slug = s.Slug, Title = "", Description = "", StarterCode = "", MethodName = "" };
                db.Problems.Add(problem);
                added++;
            }
            problem.Title = s.Title;
            problem.Description = s.Description;
            problem.Category = s.Category;
            problem.Difficulty = s.Difficulty;
            problem.MethodName = s.MethodName;
            problem.ClassName = s.ClassName;
            problem.StarterCode = s.StarterCode;
            problem.TimeLimitMs = s.TimeLimitMs;
            problem.DocLinksJson = JsonSerializer.Serialize(s.DocLinks ?? []);
            problem.TestCases = s.TestCases.Select((t, i) => new TestCase
                { Input = t.Input, Expected = t.Expected, IsHidden = t.IsHidden, Order = i }).ToList();
            problem.Translations = (s.Translations ?? []).Select(kv => new ProblemTranslation
                { Locale = kv.Key, Title = kv.Value.Title, Description = kv.Value.Description }).ToList();
        }
        db.SaveChanges();
        logger.LogInformation("Seed: {Added} problem(s) added, {Updated} updated from seed.json", added, updated);
        return added;
    }
}
